DOMAIN7 = [{'num': 7, 'topic': 7, 'title': 'Build a filter evidence matrix', 'objective': 'LO2', 'desc': 'Parentheses make mixed and/or expressions explicit.', 'build': 'Evidence CSV and packet findings', 'services': 'Wireshark, TShark, Python', 'steps': [('Prepare your lab workspace. Open this lab folder in a terminal. Windows uses py -3 in place of python3. Wireshark GUI alone is sufficient for the investigation; CLI scripts require TShark on PATH. Run the fixture verification first.', 'python3 scripts/verify.py'), ('Open data/branch-office.pcap. Apply dns.flags.rcode == 3 and record the returned response frame. Clear the filter and apply tcp.flags.syn == 1.', ''), ('Compare (ip.src == 192.0.2.10 && udp.port == 53) || tcp.port == 80 with ip.src == 192.0.2.10 && (udp.port == 53 || tcp.port == 80). Record both counts and the direction excluded by the second expression.', ''), ('Apply !(ip.addr == 192.0.2.53). Verify that DNS packets disappear; compare ip.addr != 192.0.2.53 on Wireshark 4.6 or later. Record the actual version and equality behaviour.', ''), ('Save five useful filters in outputs/filters.txt. For each, state the question, filter and matching frame numbers; compile them with scripts/verify.py.', ''), ('Export a reproducible packet table. Record the filter, frame numbers, measurement, explanation and limitation in outputs/findings.md.', 'python3 scripts/export_evidence.py')], 'test': 'The supplied dns.flags.rcode == 3 expression matches 1 frame(s) in the specified capture. Run scripts/verify.py and compare the listed frame numbers. Keep your findings and exported table in outputs/. Explain the observed result rather than only copying a count.', 'troubleshooting': 'TShark not found: install Wireshark CLI tools and add the installation folder to PATH; on Windows use the Wireshark install directory. A filter returns zero: clear other filters, use the specified capture, and check the expression is in the display toolbar. TLS remains opaque: select the matching lab-tls.keys file by absolute path, reload, and remove a key-log preference from another lab.', 'reflection': 'Which second observation point would strengthen your conclusion?', 'challenge': 'Develop and explain an alternative filter.', 'duration': 45}]
